INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_challenge#3','math',6,2,'u1','L03','g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',3,'error','auto','⟨5/6⟩ ÷ ⟨2/6⟩ = ⟨2 1/2⟩을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?',ARRAY['M6-2-u1-X04','M6-2-u1-X20']::text[],false,'{"seq":3,"concept":"M6-2-u1-C3","difficulty":3,"kind":"error","stem":"⟨5/6⟩ ÷ ⟨2/6⟩ = ⟨2 1/2⟩을 두고 친구들이 설명했어요. 잘못 설명한 친구는 누구인가요?","options":[{"t":"민준 — 「⟨1/2⟩은 비료가 ⟨1/2⟩ L 남았다는 뜻이야.」","correct":true,"mis_target":"M6-2-u1-X04"},{"t":"서아 — 「가득 찬 컵이 2컵이야.」","mis":"M6-2-u1-X20"},{"t":"지호 — 「몫은 컵의 수를 나타내.」","mis":"M6-2-u1-X20"}],"explanation":["몫 ⟨2 1/2⟩은 컵이 2개 하고도 절반이라는 뜻이에요.","⟨1/2⟩은 컵 하나의 절반을 채운다는 뜻이지 남은 양이 아니에요.","민준이는 몫의 분수 부분을 남은 양으로 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_challenge#4','math',6,2,'u1','L03','g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',3,'mc','auto','분모가 모두 19인 분수 ⟨7/19⟩ · ⟨9/19⟩ · ⟨11/19⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?',ARRAY['M6-2-u1-X05','M6-2-u1-X03','M6-2-u1-X02']::text[],true,'{"seq":4,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"분모가 모두 19인 분수 ⟨7/19⟩ · ⟨9/19⟩ · ⟨11/19⟩ 가운데 가장 큰 분수를 가장 작은 분수로 나눈 몫은 얼마인가요?","explanation":["가장 큰 분수는 ⟨11/19⟩, 가장 작은 분수는 ⟨7/19⟩이에요.","분모가 같으니 분자끼리 나눠요 — 11 ÷ 7 = ⟨11/7⟩ = ⟨1 4/7⟩.","그래서 몫은 ⟨1 4/7⟩예요."],"variant_rule":{"fd":{"ask":"maxmin"}},"options":[{"t":"⟨1 4/7⟩","correct":true},{"t":"⟨7/11⟩","mis":"M6-2-u1-X05"},{"t":"⟨4/19⟩","mis":"M6-2-u1-X03"},{"t":"⟨11/133⟩","mis":"M6-2-u1-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_challenge#5','math',6,2,'u1','L03','g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',3,'mc','auto','몫이 가장 작은 것은 어느 것인가요?',ARRAY['M6-2-u1-X16']::text[],true,'{"seq":5,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"몫이 가장 작은 것은 어느 것인가요?","explanation":["분모가 같으니 분자끼리 나누어 몫을 구해요.","⟨9/10⟩ ÷ ⟨2/10⟩ = ⟨4 1/2⟩, ⟨10/11⟩ ÷ ⟨1/11⟩ = 10, ⟨9/13⟩ ÷ ⟨6/13⟩ = ⟨1 1/2⟩, ⟨5/9⟩ ÷ ⟨1/9⟩ = 5예요.","가장 작은 몫은 ⟨9/13⟩ ÷ ⟨6/13⟩이에요."],"variant_rule":{"fd":{"ask":"cmp","kind":"same"}},"options":[{"t":"⟨9/13⟩ ÷ ⟨6/13⟩","correct":true},{"t":"⟨9/10⟩ ÷ ⟨2/10⟩","mis":"M6-2-u1-X16"},{"t":"⟨5/9⟩ ÷ ⟨1/9⟩","mis":"M6-2-u1-X16"},{"t":"⟨10/11⟩ ÷ ⟨1/11⟩","mis":"M6-2-u1-X16"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_challenge#6','math',6,2,'u1','L03','g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',3,'mc','auto','다음 중 몫이 자연수가 아닌 것은 어느 것인가요?',ARRAY['M6-2-u1-X20']::text[],true,'{"seq":6,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"다음 중 몫이 자연수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨9/13⟩ ÷ ⟨4/13⟩","correct":true},{"t":"⟨9/13⟩ ÷ ⟨3/13⟩","mis":"M6-2-u1-X20"},{"t":"⟨12/13⟩ ÷ ⟨6/13⟩","mis":"M6-2-u1-X20"},{"t":"⟨8/13⟩ ÷ ⟨2/13⟩","mis":"M6-2-u1-X20"}],"explanation":["분모가 같으니 분자끼리 나누어 봐요.","9 ÷ 3 = 3, 12 ÷ 6 = 2, 8 ÷ 2 = 4는 나누어떨어져요.","9 ÷ 4 = ⟨2 1/4⟩은 자연수가 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 중 몫이 자연수가 아닌 것은 어느 것인가요?","options":[{"t":"⟨10/17⟩ ÷ ⟨3/17⟩","correct":true},{"t":"⟨10/17⟩ ÷ ⟨5/17⟩","mis":"M6-2-u1-X20"},{"t":"⟨12/17⟩ ÷ ⟨4/17⟩","mis":"M6-2-u1-X20"},{"t":"⟨14/17⟩ ÷ ⟨7/17⟩","mis":"M6-2-u1-X20"}],"explanation":["분자끼리 나누어 봐요.","10 ÷ 5, 12 ÷ 4, 14 ÷ 7은 나누어떨어져요.","10 ÷ 3 = ⟨3 1/3⟩은 자연수가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_challenge#7','math',6,2,'u1','L03','g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',3,'mc','auto','⟨7/8⟩ L의 물을 ⟨3/8⟩ L짜리 컵에 나누어 담으면 몫은 ⟨2 1/3⟩이에요. 이 몫의 ⟨1/3⟩이 뜻하는 것은 무엇인가요?',ARRAY['M6-2-u1-X04','M6-2-u1-X18']::text[],false,'{"seq":7,"concept":"M6-2-u1-C3","difficulty":3,"kind":"mc","stem":"⟨7/8⟩ L의 물을 ⟨3/8⟩ L짜리 컵에 나누어 담으면 몫은 ⟨2 1/3⟩이에요. 이 몫의 ⟨1/3⟩이 뜻하는 것은 무엇인가요?","options":[{"t":"셋째 컵에는 컵의 ⟨1/3⟩만큼만 찬다","correct":true},{"t":"물이 ⟨1/3⟩ L 남는다","mis":"M6-2-u1-X04"},{"t":"컵이 ⟨1/3⟩개 모자란다","mis":"M6-2-u1-X04"},{"t":"물이 ⟨1/8⟩ L 남는다는 뜻이다","mis":"M6-2-u1-X18"}],"explanation":["가득 찬 컵은 2컵이고 ⟨1/8⟩ L가 남아요.","남은 ⟨1/8⟩ L는 ⟨3/8⟩ L 컵의 ⟨1/3⟩이에요.","몫의 분수 부분은 셋째 컵이 얼마나 차는지를 뜻해요."],"asset":{"type":"fbar","bars":[{"den":8,"num":7,"grp":3,"label":"⟨7/8⟩에서 ⟨3/8⟩씩 덜어 내기"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_challenge#8','math',6,2,'u1','L03','g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',4,'essay','teacher','⟨7/8⟩ ÷ ⟨3/8⟩ = ⟨2 1/3⟩이에요. 몫의 분수 부분 ⟨1/3⟩이 「남은 양 ⟨1/3⟩ L」가 아닌 까닭을 그림이나 식으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u1-C3","difficulty":4,"kind":"essay","stem":"⟨7/8⟩ ÷ ⟨3/8⟩ = ⟨2 1/3⟩이에요. 몫의 분수 부분 ⟨1/3⟩이 「남은 양 ⟨1/3⟩ L」가 아닌 까닭을 그림이나 식으로 설명해 보세요.","answer_guide":{"answer":"예: ⟨7/8⟩에서 ⟨3/8⟩을 2번 덜어 내면 ⟨1/8⟩이 남는다. 남은 ⟨1/8⟩은 한 컵 ⟨3/8⟩의 ⟨1/3⟩이다. 몫은 「컵이 몇 개인가」를 세는 수이므로 ⟨1/3⟩은 세 번째 컵이 ⟨1/3⟩만큼 찬다는 뜻이고, 남은 양은 ⟨1/8⟩ L이다.","scoring_points":["남은 양이 ⟨1/8⟩ L임을 구했는가","⟨1/8⟩이 한 컵 ⟨3/8⟩의 ⟨1/3⟩임을 설명했는가","몫은 컵의 수를 세는 수임을 밝혔는가"]},"explanation":["⟨3/8⟩을 2번 덜어 내면 ⟨1/8⟩이 남아요.","⟨1/8⟩은 ⟨3/8⟩의 ⟨1/3⟩이에요.","몫은 컵의 수 — ⟨1/3⟩은 셋째 컵이 찬 만큼이에요."],"asset":{"type":"fbar","bars":[{"den":8,"num":7,"grp":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_challenge#9','math',6,2,'u1','L03','g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',4,'essay','teacher','분모가 모두 19인 분수 ⟨7/19⟩, ⟨9/19⟩, ⟨11/19⟩ 가운데 두 개를 골라 몫이 가장 큰 나눗셈을 만들고, 그렇게 고른 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u1-C3","difficulty":4,"kind":"essay","stem":"분모가 모두 19인 분수 ⟨7/19⟩, ⟨9/19⟩, ⟨11/19⟩ 가운데 두 개를 골라 몫이 가장 큰 나눗셈을 만들고, 그렇게 고른 까닭을 설명해 보세요.","answer_guide":{"answer":"예: ⟨11/19⟩ ÷ ⟨7/19⟩ = 11 ÷ 7 = ⟨1 4/7⟩. 분모가 같으니 몫은 분자끼리 나눈 값인데, 나누어지는 수가 클수록·나누는 수가 작을수록 몫이 커지므로 가장 큰 11을 가장 작은 7로 나누어야 한다.","scoring_points":["⟨11/19⟩ ÷ ⟨7/19⟩을 골랐는가","몫 ⟨1 4/7⟩를 바르게 구했는가","가장 큰 수를 가장 작은 수로 나누는 까닭을 설명했는가"]},"explanation":["분모가 같으니 몫은 분자끼리 나눈 값이에요.","나누어지는 수는 크게, 나누는 수는 작게 해야 몫이 커요.","⟨11/19⟩ ÷ ⟨7/19⟩ = ⟨1 4/7⟩가 가장 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L03_challenge#10','math',6,2,'u1','L03','g6_2_math_u1_L03_challenge','lesson_challenge','M6-2-u1-C3',4,'mc','auto','⟨□/13⟩ ÷ ⟨4/13⟩의 몫이 ⟨1 1/4⟩이에요. □에 알맞은 수는 얼마인가요?',ARRAY['M6-2-u1-X03','M6-2-u1-X02','M6-2-u1-X05']::text[],true,'{"seq":10,"concept":"M6-2-u1-C3","difficulty":4,"kind":"mc","stem":"⟨□/13⟩ ÷ ⟨4/13⟩의 몫이 ⟨1 1/4⟩이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"9","mis":"M6-2-u1-X03"},{"t":"4","mis":"M6-2-u1-X02"},{"t":"1","mis":"M6-2-u1-X05"}],"explanation":["분모가 같으니 몫은 □ ÷ 4예요.","⟨1 1/4⟩ = ⟨5/4⟩니 □ ÷ 4 = ⟨5/4⟩예요.","그래서 □는 5예요."],"variant_rule":{"alt":[{"stem":"⟨□/11⟩ ÷ ⟨3/11⟩의 몫이 ⟨2 1/3⟩이에요. □에 알맞은 수는 얼마인가요?","options":[{"t":"7","correct":true},{"t":"10","mis":"M6-2-u1-X03"},{"t":"3","mis":"M6-2-u1-X02"},{"t":"6","mis":"M6-2-u1-X15"}],"explanation":["몫은 □ ÷ 3이에요.","⟨2 1/3⟩ = ⟨7/3⟩이니 □ ÷ 3 = ⟨7/3⟩이에요.","□는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_basic#1','math',6,2,'u1','L04','g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',1,'mc','auto','⟨2/5⟩ ÷ ⟨2/15⟩를 통분한 것은 어느 것인가요?',ARRAY['M6-2-u1-X07']::text[],true,'{"seq":1,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨2/5⟩ ÷ ⟨2/15⟩를 통분한 것은 어느 것인가요?","explanation":["5와 15의 최소공배수 15를 공통분모로 해요.","⟨2/5⟩는 ⟨6/15⟩, ⟨2/15⟩는 ⟨2/15⟩가 돼요 — 분모를 바꾼 만큼 분자도 바꿔요.","통분하면 ⟨6/15⟩ ÷ ⟨2/15⟩예요."],"variant_rule":{"fd":{"ask":"diff","form":"tong"}},"options":[{"t":"⟨6/15⟩ ÷ ⟨2/15⟩","correct":true},{"t":"⟨2/15⟩ ÷ ⟨2/15⟩","mis":"M6-2-u1-X07"},{"t":"⟨2/5⟩ ÷ ⟨2/15⟩","mis":"M6-2-u1-X07"},{"t":"⟨30/15⟩ ÷ ⟨10/15⟩","mis":"M6-2-u1-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_basic#2','math',6,2,'u1','L04','g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',1,'mc','auto','⟨3/4⟩ ÷ ⟨3/8⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":2,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ ÷ ⟨3/8⟩의 몫은 얼마인가요?","explanation":["분모가 다르니 먼저 통분해요 — ⟨6/8⟩ ÷ ⟨3/8⟩.","분자끼리 나누면 6 ÷ 3 = 2예요.","그래서 몫은 2예요."],"variant_rule":{"fd":{"ask":"diff","form":"ans"}},"options":[{"t":"2","correct":true},{"t":"1","mis":"M6-2-u1-X06"},{"t":"⟨1/2⟩","mis":"M6-2-u1-X05"},{"t":"⟨9/32⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_basic#3','math',6,2,'u1','L04','g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',1,'mc','auto','⟨1/3⟩ ÷ ⟨5/6⟩의 몫은 얼마인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":3,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨1/3⟩ ÷ ⟨5/6⟩의 몫은 얼마인가요?","explanation":["분모가 다르니 먼저 통분해요 — ⟨2/6⟩ ÷ ⟨5/6⟩.","분자끼리 나누면 2 ÷ 5 = ⟨2/5⟩예요.","그래서 몫은 ⟨2/5⟩예요."],"variant_rule":{"fd":{"ask":"diff","form":"ans"}},"options":[{"t":"⟨2/5⟩","correct":true},{"t":"⟨1/5⟩","mis":"M6-2-u1-X06"},{"t":"⟨2 1/2⟩","mis":"M6-2-u1-X05"},{"t":"⟨5/18⟩","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_basic#4','math',6,2,'u1','L04','g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',1,'mc','auto','⟨3/4⟩ ÷ ⟨2/5⟩를 계산할 때 먼저 통분을 하는 까닭은 무엇인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X02']::text[],false,'{"seq":4,"concept":"M6-2-u1-C4","difficulty":1,"kind":"mc","stem":"⟨3/4⟩ ÷ ⟨2/5⟩를 계산할 때 먼저 통분을 하는 까닭은 무엇인가요?","options":[{"t":"분모가 다르면 조각의 크기가 달라 개수끼리 견줄 수 없어서","correct":true},{"t":"통분을 하면 분자가 커져 계산이 쉬워져서","mis":"M6-2-u1-X06"},{"t":"나누는 수를 자연수로 만들기 위해서","mis":"M6-2-u1-X06"},{"t":"분모끼리 나누어야 해서","mis":"M6-2-u1-X02"}],"explanation":["⟨3/4⟩과 ⟨2/5⟩는 크기가 다른 조각을 센 수예요.","조각 크기가 다르면 개수끼리 나눌 수 없어요.","통분은 두 분수를 같은 조각으로 다시 세는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_basic#5','math',6,2,'u1','L04','g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',2,'sa','auto','⟨3/7⟩ ÷ ⟨5/8⟩를 통분해 계산할 때 몫 ⟨□/35⟩의 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-2-u1-C4","difficulty":2,"kind":"sa","stem":"⟨3/7⟩ ÷ ⟨5/8⟩를 통분해 계산할 때 몫 ⟨□/35⟩의 분자에 오는 수는 얼마인가요? 숫자로 쓰세요.","explanation":["공통분모 56으로 통분하면 ⟨24/56⟩ ÷ ⟨35/56⟩예요.","분자끼리 나누면 24 ÷ 35 = ⟨24/35⟩예요.","분자에 오는 수는 24예요."],"variant_rule":{"fd":{"ask":"diff","form":"num"}},"answer":["24"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_basic#6','math',6,2,'u1','L04','g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',2,'ox','auto','⟨2/5⟩ ÷ ⟨3/8⟩은 분모가 달라도 분자끼리 바로 나누어 2 ÷ 3 = ⟨2/3⟩예요.',ARRAY['M6-2-u1-X06']::text[],false,'{"seq":6,"concept":"M6-2-u1-C4","difficulty":2,"kind":"ox","stem":"⟨2/5⟩ ÷ ⟨3/8⟩은 분모가 달라도 분자끼리 바로 나누어 2 ÷ 3 = ⟨2/3⟩예요.","answer":"X","reason_options":[{"t":"⟨1/5⟩ 조각과 ⟨1/8⟩ 조각은 크기가 달라 먼저 통분해야 해서","correct":true},{"t":"분자끼리가 아니라 분모끼리 나누어야 해서","mis":"M6-2-u1-X06"}],"mis":"M6-2-u1-X06","explanation":["분자끼리 바로 나누려면 조각 크기가 같아야 해요.","통분하면 ⟨16/40⟩ ÷ ⟨15/40⟩ = 16 ÷ 15예요.","몫은 ⟨1 1/15⟩ — ⟨2/3⟩가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_basic#7','math',6,2,'u1','L04','g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',2,'match','auto','나눗셈식과 통분한 식을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M6-2-u1-C4","difficulty":2,"kind":"match","stem":"나눗셈식과 통분한 식을 알맞게 이으세요.","pairs":[{"l":"⟨1/3⟩ ÷ ⟨5/6⟩","r":"⟨2/6⟩ ÷ ⟨5/6⟩"},{"l":"⟨3/4⟩ ÷ ⟨2/5⟩","r":"⟨15/20⟩ ÷ ⟨8/20⟩"},{"l":"⟨2/5⟩ ÷ ⟨2/15⟩","r":"⟨6/15⟩ ÷ ⟨2/15⟩"}],"mis":"M6-2-u1-X07","explanation":["두 분모의 최소공배수를 공통분모로 해요.","3과 6은 6, 4와 5는 20, 5와 15는 15예요.","분모를 바꾼 만큼 분자도 바꿔요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 나눗셈식과 통분한 식을 알맞게 이으세요.","pairs":[{"l":"⟨1/2⟩ ÷ ⟨3/8⟩","r":"⟨4/8⟩ ÷ ⟨3/8⟩"},{"l":"⟨2/3⟩ ÷ ⟨3/4⟩","r":"⟨8/12⟩ ÷ ⟨9/12⟩"},{"l":"⟨5/6⟩ ÷ ⟨1/9⟩","r":"⟨15/18⟩ ÷ ⟨2/18⟩"}],"explanation":["최소공배수를 공통분모로 해요.","2와 8은 8, 3과 4는 12, 6과 9는 18이에요.","분자도 같이 바꿔요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_basic#8','math',6,2,'u1','L04','g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',2,'mc','auto','대파 길이는 ⟨3/4⟩ m, 부추 길이는 ⟨3/8⟩ m예요. 대파 길이는 부추 길이의 몇 배인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":8,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"대파 길이는 ⟨3/4⟩ m, 부추 길이는 ⟨3/8⟩ m예요. 대파 길이는 부추 길이의 몇 배인가요?","explanation":["몇 배인지는 ⟨3/4⟩ ÷ ⟨3/8⟩으로 구해요.","통분하면 ⟨6/8⟩ ÷ ⟨3/8⟩ = 6 ÷ 3이에요.","그래서 2배예요."],"variant_rule":{"fd":{"ask":"diff","form":"story"}},"options":[{"t":"2배","correct":true},{"t":"1배","mis":"M6-2-u1-X06"},{"t":"⟨1/2⟩배","mis":"M6-2-u1-X05"},{"t":"⟨9/32⟩배","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_basic#9','math',6,2,'u1','L04','g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',2,'mc','auto','⟨8/9⟩ ÷ ⟨5/8⟩를 통분한 것은 어느 것인가요?',ARRAY['M6-2-u1-X07']::text[],true,'{"seq":9,"concept":"M6-2-u1-C4","difficulty":2,"kind":"mc","stem":"⟨8/9⟩ ÷ ⟨5/8⟩를 통분한 것은 어느 것인가요?","explanation":["9와 8의 최소공배수 72를 공통분모로 해요.","⟨8/9⟩은 ⟨64/72⟩, ⟨5/8⟩는 ⟨45/72⟩가 돼요 — 분모를 바꾼 만큼 분자도 바꿔요.","통분하면 ⟨64/72⟩ ÷ ⟨45/72⟩예요."],"variant_rule":{"fd":{"ask":"diff","form":"tong"}},"options":[{"t":"⟨64/72⟩ ÷ ⟨45/72⟩","correct":true},{"t":"⟨8/72⟩ ÷ ⟨5/72⟩","mis":"M6-2-u1-X07"},{"t":"⟨64/72⟩ ÷ ⟨5/8⟩","mis":"M6-2-u1-X07"},{"t":"⟨8/9⟩ ÷ ⟨45/72⟩","mis":"M6-2-u1-X07"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_math_u1_L04_basic#10','math',6,2,'u1','L04','g6_2_math_u1_L04_basic','lesson_basic','M6-2-u1-C4',3,'mc','auto','종이 팩 무게는 ⟨7/9⟩ kg, 우유 팩 무게는 ⟨7/12⟩ kg이에요. 종이 팩 무게는 우유 팩 무게의 몇 배인가요?',ARRAY['M6-2-u1-X06','M6-2-u1-X05','M6-2-u1-X12']::text[],true,'{"seq":10,"concept":"M6-2-u1-C4","difficulty":3,"kind":"mc","stem":"종이 팩 무게는 ⟨7/9⟩ kg, 우유 팩 무게는 ⟨7/12⟩ kg이에요. 종이 팩 무게는 우유 팩 무게의 몇 배인가요?","explanation":["몇 배인지는 ⟨7/9⟩ ÷ ⟨7/12⟩로 구해요.","통분하면 ⟨28/36⟩ ÷ ⟨21/36⟩ = 28 ÷ 21이에요.","그래서 ⟨1 1/3⟩배예요."],"variant_rule":{"fd":{"ask":"diff","form":"story"}},"options":[{"t":"⟨1 1/3⟩배","correct":true},{"t":"1배","mis":"M6-2-u1-X06"},{"t":"⟨3/4⟩배","mis":"M6-2-u1-X05"},{"t":"⟨49/108⟩배","mis":"M6-2-u1-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
